#include "aseprite_save_policy.h"
#include "aseprite_io.h"
#include "editor_preferences.h"
#include <iostream>
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{using namespace moon;check(isAsepriteSavePath("x.ASE")&&isAsepriteSavePath("x.AsEpRiTe")&&!isAsepriteSavePath("x.ase.bak"),"ASE source extension");check(normalizedAsepriteSavePath("x.moonsprite")==std::filesystem::path("x.aseprite")&&normalizedAsepriteSavePath("x.ase",L".aseprite")==std::filesystem::path("x.ase"),"ASE Save As normalization");Document d(2,1);d.addFrame();check(asepriteSaveIssues(d).empty(),"ASE preserves animation structure");d.setSelectedFramesDisabled(true);check(asepriteSaveIssues(d)==std::vector<std::string>{"frameFlags"},"ASE disabled frame warning");d.beginStroke({0,0},0xffffffff);d.commitStroke();check(d.createAttachedMask(d.layer().id,d.frame().id),"Mask loss fixture admission");auto issues=asepriteSaveIssues(d);check(std::find(issues.begin(),issues.end(),"effects")!=issues.end()&&!asepriteApprovalCovers({"frameFlags"},issues),"ASE new issue invalidates approval");auto state=d.timeline().state().masks.size();acceptAsepriteSaved(d,"saved.ase",true,false);check(d.dirty()&&d.sourceFilePath()==std::filesystem::path("saved.ase"),"Newer generation must remain dirty");acceptAsepriteSaved(d,"saved.ase",true,true);check(!d.dirty()&&d.timeline().state().masks.size()==state&&!d.sourceArchive(),"ASE savepoint must not replace live masks or archive");preferences::RuntimeSettings pref;check(pref.flag("files.saveOriginalFormat"),"Original-format default true");pref.set("files.saveOriginalFormat","false");pref.set("files.saveFormat.Select","8");std::istringstream in(pref.encode());auto round=preferences::RuntimeSettings::decode(in);check(!round.flag("files.saveOriginalFormat")&&round.index("files.saveFormat.Select")==8,"ASE save preference roundtrip");std::cout<<"ASE save policy checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
